// Headless smoke test for index.html game script
const fs = require("fs");

const html = fs.readFileSync("index.html", "utf8");
const src = html.match(/<script>([\s\S]*)<\/script>/)[1];

// ── stubs ──────────────────────────────────────────────────────
function makeCtx() {
  const grad = { addColorStop() {} };
  const noop = () => {};
  return new Proxy({}, {
    get(t, prop) {
      if (prop === "createLinearGradient" || prop === "createRadialGradient") return () => grad;
      if (prop === "measureText") return () => ({ width: 10 });
      if (typeof prop === "string") return t[prop] !== undefined ? t[prop] : noop;
      return noop;
    },
    set(t, prop, v) { t[prop] = v; return true; },
  });
}

const listeners = { window: {}, canvas: {}, btn: {} };
function addL(map) { return (ev, fn) => { (map[ev] = map[ev] || []).push(fn); }; }

const canvasEl = {
  width: 960, height: 640,
  style: {},
  getContext: () => makeCtx(),
  addEventListener: addL(listeners.canvas),
  getBoundingClientRect: () => ({ left: 0, top: 0, width: 960, height: 640 }),
};

function makeEl(id) {
  return {
    id, style: {}, textContent: "",
    classList: { add() {}, remove() {}, toggle() {} },
    addEventListener: addL(listeners.btn),
    offsetWidth: 0,
  };
}

const els = {};
let rafCb = null;
const sandbox = {
  document: {
    getElementById: id => els[id] || (els[id] = id === "game" ? canvasEl : makeEl(id)),
    addEventListener: () => {},
  },
  window: undefined, // set below
  performance: { now: () => t },
  requestAnimationFrame: cb => { rafCb = cb; },
  localStorage: { getItem: () => null, setItem: () => {} },
  innerWidth: 1280, innerHeight: 800,
  setTimeout: (fn, ms) => { pendingTimeouts.push(fn); return 0; },
  clearTimeout: () => {},
  Math, void: undefined,
};
const g = sandbox;
g.window = {
  addEventListener: addL(listeners.window),
  AudioContext: undefined,
};

const pendingTimeouts = [];
let t = 0;

const vm = require("vm");
const ctx = vm.createContext(sandbox);
vm.runInContext(src, ctx, { filename: "game.js" });

function fire(map, ev, arg) {
  for (const fn of (map[ev] || [])) fn(arg || { preventDefault() {}, key: "", touches: [{ clientX: 500, clientY: 500 }], clientX: 500, clientY: 500 });
}

function frames(n, dtMs = 16) {
  for (let i = 0; i < n; i++) {
    t += dtMs;
    const cb = rafCb; rafCb = null;
    cb(t);
    // run due timeouts (approximate: run all pending each frame like real timers)
    while (pendingTimeouts.length) pendingTimeouts.shift()();
  }
}

// simulate: press SPACE at menu -> starts game (state READY)
fire(listeners.window, "keydown", { key: " ", preventDefault() {} });
frames(5);

// launch ball via space
fire(listeners.window, "keydown", { key: " ", preventDefault() {} });
frames(60);          // ~1s of play: ball should be moving and hitting things

// move paddle around with keys
fire(listeners.window, "keydown", { key: "ArrowLeft", preventDefault() {} });
frames(10);
fire(listeners.window, "keyup", { key: "ArrowLeft" });
fire(listeners.window, "keydown", { key: "ArrowRight", preventDefault() {} });
frames(10);
fire(listeners.window, "keyup", { key: "ArrowRight" });

// mouse move + click
fire(listeners.canvas, "mousemove", { clientX: 300, clientY: 400 });
frames(5);
fire(listeners.canvas, "mousedown", {});
frames(30);

// pause / resume
fire(listeners.window, "keydown", { key: "p" });
frames(5);
fire(listeners.window, "keydown", { key: "Escape" });
frames(5);

// let it run a while — exercise brick collisions, power-ups, possible life loss / level clear
frames(600);

console.log("smoke test completed without exceptions");

