// Behavioral smoke test: asserts game state progression
const fs = require("fs");
const vm = require("vm");

const html = fs.readFileSync(process.env.GAME_HTML, "utf8");
let src = html.match(/<script>([\s\S]*)<\/script>/)[1];

// Inject debug hook right after the "use strict" prologue
src = src.replace('"use strict";', `"use strict";
globalThis.__dbg = () => ({ state: G.state, score: G.score, level: G.level,
  lives: G.lives, balls: balls ? balls.length : 0,
  bricksAlive: bricks ? bricks.filter(b => b.alive).length : -1,
  stuck: !!stuckBall, particles: particles ? particles.length : 0,
  powers: powerups ? powerups.length : 0 });`);

function makeCtx() {
  const grad = { addColorStop() {} };
  return new Proxy({}, {
    get(t, prop) {
      if (prop === "createLinearGradient" || prop === "createRadialGradient") return () => grad;
      if (prop === "measureText") return () => ({ width: 10 });
      if (typeof prop === "string") return t[prop] !== undefined ? t[prop] : () => {};
      return () => {};
    },
    set(t, prop, v) { t[prop] = v; return true; },
  });
}

const listeners = { window: {}, canvas: {} };
const addL = map => (ev, fn) => { (map[ev] = map[ev] || []).push(fn); };

const canvasEl = {
  width: 960, height: 640, style: {},
  getContext: () => makeCtx(),
  addEventListener: addL(listeners.canvas),
  getBoundingClientRect: () => ({ left: 0, top: 0, width: 960, height: 640 }),
};
function makeEl(id) {
  return { id, style: {}, textContent: "",
    classList: { add() {}, remove() {} },
    addEventListener: addL({}), offsetWidth: 0 };
}
const els = {};
let rafCb = null;
const pending = [];
let t = 0;
const sandbox = {
  document: { getElementById: id => els[id] || (els[id] = id === "game" ? canvasEl : makeEl(id)), addEventListener: () => {} },
  performance: { now: () => t },
  requestAnimationFrame: cb => { rafCb = cb; },
  localStorage: { getItem: () => null, setItem: () => {} },
  setTimeout: fn => { pending.push(fn); return 0; },
  clearTimeout: () => {},
};
sandbox.window = { addEventListener: addL(listeners.window), AudioContext: undefined };
sandbox.addEventListener = sandbox.window.addEventListener;
sandbox.innerWidth = 1280; sandbox.innerHeight = 800;

vm.createContext(sandbox);
vm.runInContext(src, sandbox, { filename: "game.js" });

const fire = (map, ev, arg) => { for (const fn of (map[ev] || [])) fn(Object.assign({ preventDefault() {} }, arg)); };
const dbg = () => sandbox.__dbg();
const frames = (n, dt = 16) => { for (let i = 0; i < n; i++) { t += dt; const cb = rafCb; rafCb = null; cb(t); while (pending.length) pending.shift()(); } };

let failed = 0;
const check = (name, cond) => { console.log((cond ? "PASS" : "FAIL") + "  " + name); if (!cond) failed++; };

// Menu -> READY via SPACE
check("starts in MENU", dbg().state === 0);
fire(listeners.window, "keydown", { key: " " });
check("space starts game (READY)", dbg().state === 1);
check("bricks loaded", dbg().bricksAlive > 0);
check("ball stuck to paddle", dbg().stuck === true);

// Launch
fire(listeners.window, "keydown", { key: " " });
check("launch -> PLAY", dbg().state === 2);
check("ball free", dbg().stuck === false);
frames(30);
check("ball stays in play after 0.5s", dbg().balls >= 1 || dbg().state === 1);

// Simulate paddle tracking the ball for a long time via mousemove (center-ish)
for (let i = 0; i < 40; i++) { fire(listeners.canvas, "mousemove", { clientX: 480, clientY: 500 }); frames(15); }

const d1 = dbg();
check("game ran (some outcome reached)", d1.score > 0 || d1.lives < 3 || d1.state === 1 || d1.state === 2 || d1.state === 4);

// Pause / resume
fire(listeners.window, "keydown", { key: "p" });
check("P pauses", dbg().state === 3);
fire(listeners.window, "keydown", { key: "p" });
check("P resumes", dbg().state === 2 || dbg().state === 1);

// Force-run to game over: never move paddle, ball drops repeatedly
frames(1200, 16);
const d2 = dbg();
check("life/gameover logic reachable", d2.lives <= 3);

// Level clear path: verify level never exceeds LEVELS length and no crash
frames(2000, 16);
const d3 = dbg();
check("level bounded", d3.level >= 0 && d3.level < 8);
check("score non-negative", d3.score >= 0);

console.log(failed === 0 ? "\nALL CHECKS PASSED" : `\n${failed} CHECK(S) FAILED`);
process.exit(failed === 0 ? 0 : 1);

